// Espera una hoja config con columnas: campo | valor
// Ejemplo:
// feed_url | https://TU-FEED-ATOM.xml
// keywords | software, inteligencia artificial, datos
// exclude_keywords | limpieza, jardinería
// provincia | Valencia
// cpv | 72000000,48000000
// importe_min | 15000
// email_destino | tu@email.com
// max_resultados | 25

const rows = $input.all().map(i => i.json);
const cfg = {};
for (const row of rows) {
  const key = String(row.campo || row.key || '').trim();
  const val = String(row.valor || row.value || '').trim();
  if (key) cfg[key] = val;
}

function list(name) {
  return String(cfg[name] || '')
    .split(',')
    .map(s => s.trim().toLowerCase())
    .filter(Boolean);
}

return [{
  json: {
    feed_url: cfg.feed_url || 'PEGA_AQUI_URL_ATOM_XML',
    keywords: list('keywords'),
    exclude_keywords: list('exclude_keywords'),
    provincias: list('provincia'),
    cpvs: list('cpv'),
    importe_min: Number(String(cfg.importe_min || '0').replace(/[^\d.,-]/g, '').replace(',', '.')) || 0,
    email_destino: cfg.email_destino || '',
    max_resultados: Number(cfg.max_resultados || 25) || 25
  }
}];

// Base: descarga un feed ATOM/XML, extrae entries y aplica filtros.
// Nota: si tu URL es ZIP, usa primero un nodo de descompresión o apunta a XML directo.
const cfg = $json;
if (!cfg.feed_url || cfg.feed_url.includes('PEGA_AQUI')) {
  throw new Error('Falta feed_url en la hoja config');
}

const res = await fetch(cfg.feed_url);
if (!res.ok) throw new Error(`Error descargando feed: ${res.status} ${res.statusText}`);
const xml = await res.text();

function tag(block, names) {
  for (const name of names) {
    const re = new RegExp(`<[^>]*:?${name}[^>]*>([\\s\\S]*?)<\\/[^>]*:?${name}>`, 'i');
    const m = block.match(re);
    if (m) return clean(m[1]);
  }
  return '';
}
function clean(s) {
  return String(s || '')
    .replace(/<!\[CDATA\[/g, '')
    .replace(/\]\]>/g, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\s+/g, ' ')
    .trim();
}
function link(block) {
  const m = block.match(/<link[^>]+href=["']([^"']+)["']/i);
  return m ? m[1] : '';
}
function amount(text) {
  const m = text.match(/(?:importe|presupuesto|valor estimado)[^\d]{0,30}([\d.]+,\d{2}|[\d.]+)/i);
  if (!m) return 0;
  return Number(m[1].replace(/\./g, '').replace(',', '.')) || 0;
}
function includesAny(text, arr) {
  if (!arr || arr.length === 0) return true;
  const t = text.toLowerCase();
  return arr.some(x => t.includes(x));
}
function excludesAll(text, arr) {
  if (!arr || arr.length === 0) return true;
  const t = text.toLowerCase();
  return !arr.some(x => t.includes(x));
}

const entries = [...xml.matchAll(/<entry[\s\S]*?<\/entry>/gi)].map(m => m[0]);
const out = [];

for (const e of entries) {
  const title = tag(e, ['title']);
  const summary = tag(e, ['summary', 'content']);
  const id = tag(e, ['id']) || link(e) || title;
  const updated = tag(e, ['updated', 'published']);
  const url = link(e);
  const text = `${title} ${summary} ${id}`;
  const importe = amount(text);

  if (!includesAny(text, cfg.keywords)) continue;
  if (!excludesAll(text, cfg.exclude_keywords)) continue;
  if (cfg.provincias?.length && !includesAny(text, cfg.provincias)) continue;
  if (cfg.cpvs?.length && !includesAny(text, cfg.cpvs)) continue;
  if (cfg.importe_min && importe && importe < cfg.importe_min) continue;

  out.push({ json: { id, title, summary, updated, url, importe, email_destino: cfg.email_destino } });
  if (out.length >= cfg.max_resultados) break;
}

return out;

// Agrupa todos los resultados en un único email HTML.
const items = $input.all();
if (items.length === 0) return [];

const to = items[0].json.email_destino;
const rows = items.map((i, idx) => {
  const j = i.json;
  return `
    <li style="margin-bottom:16px">
      <strong>${j.title || 'Sin título'}</strong><br>
      Fecha: ${j.updated || '-'}<br>
      Importe detectado: ${j.importe || '-'}<br>
      ${j.url ? `<a href="${j.url}">Abrir licitación</a><br>` : ''}
      <small>${(j.summary || '').slice(0, 500)}</small>
    </li>`;
}).join('');

return [{
  json: {
    to,
    subject: `Nuevas licitaciones encontradas: ${items.length}`,
    html: `<h2>Nuevas licitaciones encontradas</h2><ol>${rows}</ol>`,
    count: items.length
  }
}];
